/** Immutable evidence emitted after one file-local OpenRewrite pass. */
public record M3TranspilePassResult(
        int ordinal,
        String passId,
        String recipeName,
        String sourcePath,
        String beforeSha256,
        String afterSha256,
        boolean changed) {

    public M3TranspilePassResult {
