/**
 * Second-pass M3 atomize/patternize signal chain.
 *
 * <p>The chain is evidence-only. Independent AST/LST recognizers fan out in parallel, masked
 * lexical regex contributes bounded nomination cues only, and deterministic content-addressed
 * fan-in produces pattern candidates, contract-risk residue and a fixed-point root. No handler
 * can mutate source, certify semantic equivalence, or promote a candidate.</p>
 */
public final class M3AtomPatternSignalChainRecipe
        extends ScanningRecipe<M3AtomPatternSignalChainRecipe.Inventory> {
    private static final String ZERO_ROOT = "0".repeat(64);
    private static final int REQUIRED_FIXED_POINT_PASSES = 3;

    private static final List<SignalHandler> PRIMARY_HANDLERS = List.of(
            new StructuralHandler(),
            new ControlFlowHandler(),
            new EffectContractHandler(),
            new MaskedRegexHandler());

    @JsonProperty("sourceFilePattern")
    private final String sourceFilePattern;

    @JsonProperty("maxPasses")
    private final Integer maxPasses;

    private final transient SignalTable signals = new SignalTable(this);
    private final transient CandidateTable candidates = new CandidateTable(this);
    private final transient ResidueTable residue = new ResidueTable(this);
    private final transient DagTable dag = new DagTable(this);
    private final transient PassTable passes = new PassTable(this);
    private final transient SummaryTable summary = new SummaryTable(this);

    public M3AtomPatternSignalChainRecipe() {
        this("**/*.java", 4);
    }

    @JsonCreator
    public M3AtomPatternSignalChainRecipe(
            @JsonProperty("sourceFilePattern") final String sourceFilePattern,
            @JsonProperty("maxPasses") final Integer maxPasses) {
        this.sourceFilePattern = token(sourceFilePattern, "sourceFilePattern");
        final int budget = maxPasses == null ? 4 : maxPasses;
        if (budget < 1 || budget > 16) {
            throw new IllegalArgumentException("maxPasses");
        }
        this.maxPasses = budget;
    }

    @Override
    public String getDisplayName() {
        return "M3 atom/pattern signal chain";
    }

    @Override
    public String getDescription() {
        return "Runs parallel structural/control/effect/masked-lexical recognizers, then "
                + "deterministically reduces pattern candidates, contract-risk residue and a "
                + "content-addressed fixed-point DAG without source mutation.";
    }

    @Override
    public Set<String> getTags() {
        return Set.of(
                "synexia",
                "m3",
                "atomization",
                "patternization",
                "iop",
                "chain-of-responsibility",
                "dag",
                "masked-regex",
                "fixed-point",
                "candidate-only",
                "read-only");
    }

    @Override
    public int maxCycles() {
        return 1;
    }

    @Override
    public boolean causesAnotherCycle() {
        return false;
    }

    @Override
    public Inventory getInitialValue(final ExecutionContext context) {
        return new Inventory();
    }

    @Override
    public TreeVisitor<?, ExecutionContext> getScanner(final Inventory inventory) {
        final TreeVisitor<Tree, ExecutionContext> visitor =
                new TreeVisitor<>() {
                    @Override
                    public Tree preVisit(final Tree tree, final ExecutionContext context) {
                        if (!(tree instanceof J.CompilationUnit unit)) {
                            return tree;
                        }
                        stopAfterPreVisit();
                        final SourceAnalysis analysis = analyze(unit);
                        inventory.observe(analysis);
                        return tree;
                    }
                };
        return Preconditions.check(
                new FindSourceFiles(sourceFilePattern).getVisitor(),
                visitor);
    }

    @Override
    public Collection<? extends SourceFile> generate(
            final Inventory inventory,
            final ExecutionContext context) {
        final List<SourceAnalysis> analyses = inventory.analyses();
        if (analyses.isEmpty()) {
            throw new IllegalStateException(
                    "M3 atom/pattern signal chain matched no Java sources");
        }

        // Admit the budget before publishing any evidence rows.
        if (maxPasses < REQUIRED_FIXED_POINT_PASSES) {
            throw new IllegalStateException(
                    "M3 atom/pattern signal chain did not reach fixed point within "
                            + maxPasses
                            + " passes; required="
                            + REQUIRED_FIXED_POINT_PASSES);
        }

        for (SourceAnalysis analysis : analyses) {
            analysis.signalRows().forEach(row -> signals.insertRow(context, row));
            analysis.candidateRows().forEach(row -> candidates.insertRow(context, row));
            analysis.residueRows().forEach(row -> residue.insertRow(context, row));
            analysis.dagRows().forEach(row -> dag.insertRow(context, row));
        }

        final String signalRoot = digest(
                "M3_SIGNAL_REPOSITORY_V1",
                analyses.stream().map(SourceAnalysis::signalRoot).sorted().toList());
        final String fullRoot = digest(
                "M3_ATOM_PATTERN_REPOSITORY_V1",
                analyses.stream().map(SourceAnalysis::fullRoot).sorted().toList());

        passes.insertRow(
                context,
                new PassRow(1, "PRIMARY_SIGNAL_FAN_IN", ZERO_ROOT, signalRoot, true, false));
        passes.insertRow(
                context,
                new PassRow(
                        2,
                        "PATTERN_RISK_FAN_IN",
                        signalRoot,
                        fullRoot,
                        !signalRoot.equals(fullRoot),
                        false));
        passes.insertRow(
                context,
                new PassRow(3, "FIXED_POINT_RECHECK", fullRoot, fullRoot, false, true));

        final int signalCount = analyses.stream().mapToInt(a -> a.signalRows().size()).sum();
        final int candidateCount =
                analyses.stream().mapToInt(a -> a.candidateRows().size()).sum();
        final int residueCount = analyses.stream().mapToInt(a -> a.residueRows().size()).sum();
        summary.insertRow(
                context,
                new SummaryRow(
                        analyses.size(),
                        signalCount,
                        candidateCount,
                        residueCount,
                        maxPasses,
                        REQUIRED_FIXED_POINT_PASSES,
                        true,
                        fullRoot,
                        false,
                        false,
                        false));
        return List.of();
    }

    public String sourceFilePattern() {
        return sourceFilePattern;
    }

    public int passBudget() {
        return maxPasses;
    }

    public boolean mutationAuthority() {
        return false;
    }

    public boolean semanticEquivalenceAuthority() {
        return false;
    }

    public boolean promotionAuthority() {
        return false;
    }

    private static SourceAnalysis analyze(final J.CompilationUnit unit) {
        final String path = normalized(unit);
        final String source = unit.printAll();
        final String masked = M3CodeSignalChain.maskedSource(unit, () -> { });
        if (masked.length() != source.length()) {
            throw new IllegalStateException("LST mask changed source length");
        }
        for (int index = 0; index < source.length(); index++) {
            final char original = source.charAt(index);
            final char projected = masked.charAt(index);
            if ((original == '\n' || original == '\r'
                    || projected == '\n' || projected == '\r') && original != projected) {
                throw new IllegalStateException("LST mask changed line coordinates");
            }
        }
        final SourceContext sourceContext =
                new SourceContext(
                        path,
                        source,
                        masked,
                        classFacts(unit),
                        methodFacts(unit));

        final List<SignalRow> primary =
                PRIMARY_HANDLERS.parallelStream()
                        .flatMap(handler -> handler.signals(sourceContext).stream())
                        .sorted(SignalRow.ORDER)
                        .toList();

        final List<CandidateRow> candidates =
                recognizeCandidates(sourceContext, primary).parallelStream()
                        .sorted(CandidateRow.ORDER)
                        .toList();

        final List<ResidueRow> residue = classifyResidue(sourceContext, primary, candidates);

        final TreeMap<String, List<SignalRow>> byHandler = new TreeMap<>();
        for (SignalRow signal : primary) {
            byHandler.computeIfAbsent(signal.handler(), ignored -> new ArrayList<>()).add(signal);
        }

        final ArrayList<DagRow> dag = new ArrayList<>();
        final ArrayList<String> handlerRoots = new ArrayList<>();
        int handlerOrdinal = 0;
        for (SignalHandler handler : PRIMARY_HANDLERS.stream()
                .sorted(Comparator.comparing(SignalHandler::id))
                .toList()) {
            final List<String> canonical =
                    byHandler.getOrDefault(handler.id(), List.of()).stream()
                            .map(SignalRow::canonical)
                            .sorted()
                            .toList();
            final String root = digest(
                    "M3_SIGNAL_HANDLER_V1:" + handler.id(),
                    concat(List.of(path), canonical));
            handlerRoots.add(root);
            dag.add(
                    new DagRow(
                            path,
                            "",
                            root,
                            "HANDLER_ROOT:" + handler.id(),
                            handlerOrdinal++,
                            false,
                            false));
        }

        final String signalRoot =
                digest("M3_SIGNAL_SOURCE_V1", concat(List.of(path), handlerRoots));
        int ordinal = 0;
        for (String handlerRoot : handlerRoots.stream().sorted().toList()) {
            dag.add(
                    new DagRow(
                            path,
                            signalRoot,
                            handlerRoot,
                            "SIGNAL_FAN_IN",
                            ordinal++,
                            false,
                            false));
        }

        final List<String> candidateCanon =
                candidates.stream().map(CandidateRow::canonical).sorted().toList();
        final List<String> residueCanon =
                residue.stream().map(ResidueRow::canonical).sorted().toList();
        final String fullRoot =
                digest(
                        "M3_ATOM_PATTERN_SOURCE_V1",
                        concat(List.of(path, signalRoot), candidateCanon, residueCanon));

        ordinal = 0;
        for (CandidateRow candidate : candidates) {
            final String child =
                    digest("M3_PATTERN_CANDIDATE_V1", List.of(candidate.canonical()));
            dag.add(
                    new DagRow(
                            path,
                            fullRoot,
                            child,
                            "PATTERN_CANDIDATE",
                            ordinal++,
                            false,
                            false));
        }
        for (ResidueRow row : residue) {
            final String child = digest("M3_SIGNAL_RESIDUE_V1", List.of(row.canonical()));
            dag.add(
                    new DagRow(
                            path,
                            fullRoot,
                            child,
                            "TYPED_RESIDUE",
                            ordinal++,
                            false,
                            false));
        }

        return new SourceAnalysis(
                path,
                sha256(source),
                primary,
                candidates,
                residue,
                List.copyOf(dag),
                signalRoot,
                fullRoot);
    }

    private static List<ClassFact> classFacts(final J.CompilationUnit unit) {
        final ArrayList<ClassFact> facts = new ArrayList<>();
        new JavaIsoVisitor<List<ClassFact>>() {
            private final Deque<String> owners = new ArrayDeque<>();

            @Override
            public J.ClassDeclaration visitClassDeclaration(
                    final J.ClassDeclaration type,
                    final List<ClassFact> sink) {
                final String owner = owners.isEmpty()
                        ? type.getSimpleName()
                        : owners.peek() + "$" + type.getSimpleName();
                final int methods =
                        (int)
                                type.getBody().getStatements().stream()
                                        .filter(J.MethodDeclaration.class::isInstance)
                                        .count();
                sink.add(new ClassFact(owner, methods));
                owners.push(owner);
                try {
                    return super.visitClassDeclaration(type, sink);
                } finally {
                    owners.pop();
                }
            }
        }.visit(unit, facts);
        return List.copyOf(facts);
    }

    private static List<MethodFact> methodFacts(final J.CompilationUnit unit) {
        final ArrayList<MethodFact> facts = new ArrayList<>();
        new JavaIsoVisitor<List<MethodFact>>() {
            private final Deque<String> owners = new ArrayDeque<>();

            @Override
            public J.ClassDeclaration visitClassDeclaration(
                    final J.ClassDeclaration type,
                    final List<MethodFact> sink) {
                final String owner = owners.isEmpty()
                        ? type.getSimpleName()
                        : owners.peek() + "$" + type.getSimpleName();
                owners.push(owner);
                try {
                    return super.visitClassDeclaration(type, sink);
                } finally {
                    owners.pop();
                }
            }

            @Override
            public J.MethodDeclaration visitMethodDeclaration(
                    final J.MethodDeclaration method,
                    final List<MethodFact> sink) {
                final String owner = owners.isEmpty() ? "<top>" : owners.peek();
                sink.add(MethodFact.of(owner, method));
                return method;
            }
        }.visit(unit, facts);
        return List.copyOf(facts);
    }

    private static List<CandidateRow> recognizeCandidates(
            final SourceContext source,
            final List<SignalRow> signals) {
        final Map<String, List<SignalRow>> byMethod = new LinkedHashMap<>();
        for (SignalRow signal : signals) {
            byMethod.computeIfAbsent(
                            signal.owner() + "" + signal.method(),
                            ignored -> new ArrayList<>())
                    .add(signal);
        }

        final List<CandidateRecognizer> recognizers = List.of(
                M3AtomPatternSignalChainRecipe::strategyCandidate,
                M3AtomPatternSignalChainRecipe::stateCandidate,
                M3AtomPatternSignalChainRecipe::factoryCandidate,
                M3AtomPatternSignalChainRecipe::observerCandidate,
                M3AtomPatternSignalChainRecipe::routeCandidate,
                M3AtomPatternSignalChainRecipe::decompositionCandidate,
                M3AtomPatternSignalChainRecipe::repeatedAtomCandidate);

        return byMethod.entrySet().parallelStream()
                .flatMap(entry -> {
                    final String[] key = entry.getKey().split("", -1);
                    return recognizers.stream()
                            .map(recognizer ->
                                    recognizer.recognize(
                                            source.path(),
                                            key[0],
                                            key[1],
                                            List.copyOf(entry.getValue())))
                            .filter(Objects::nonNull);
                })
                .sorted(CandidateRow.ORDER)
                .toList();
    }

    private static CandidateRow strategyCandidate(
            final String path,
            final String owner,
            final String method,
            final List<SignalRow> rows) {
        final int branches = observed(rows, "CONTROL_BRANCH_POINTS");
        if (branches <= M3CodeSignalThresholds.MAX_BRANCH_POINTS) return null;
        return candidate(
                path,
                owner,
                method,
                "gof:strategy",
                branches,
                "AST_CONTROL_FLOW",
                evidence(rows, "CONTROL_BRANCH_POINTS", "CONTRACT_"));
    }

    private static CandidateRow stateCandidate(
            final String path,
            final String owner,
            final String method,
            final List<SignalRow> rows) {
        if (observed(rows, "SWITCH_PRESENT") <= 0 || observed(rows, "EFFECT_FIELD_WRITE") <= 0) {
            return null;
        }
        return candidate(
                path,
                owner,
                method,
                "gof:state",
                observed(rows, "SWITCH_PRESENT") + observed(rows, "EFFECT_FIELD_WRITE"),
                "AST_CONTROL_EFFECT",
                evidence(rows, "SWITCH_PRESENT", "EFFECT_FIELD_WRITE", "CONTRACT_"));
    }

    private static CandidateRow factoryCandidate(
            final String path,
            final String owner,
            final String method,
            final List<SignalRow> rows) {
        final int count = observed(rows, "CONSTRUCTION_FANOUT");
        if (count < 3) return null;
        return candidate(
                path,
                owner,
                method,
                "gof:factory-method",
                count,
                "AST_CONSTRUCTION",
                evidence(rows, "CONSTRUCTION_FANOUT", "CONTRACT_"));
    }

    private static CandidateRow observerCandidate(
            final String path,
            final String owner,
            final String method,
            final List<SignalRow> rows) {
        final int ast = observed(rows, "LISTENER_FANOUT");
        final int lexical = observed(rows, "OBSERVER_TEXT_CUE");
        if (ast <= 0 && lexical <= 0) return null;
        return candidate(
                path,
                owner,
                method,
                "gof:observer",
                Math.max(ast, lexical),
                ast > 0 ? "AST_INVOCATION" : "MASKED_REGEX_CUE",
                evidence(rows, "LISTENER_FANOUT", "OBSERVER_TEXT_CUE", "CONTRACT_"));
    }

    private static CandidateRow routeCandidate(
            final String path,
            final String owner,
            final String method,
            final List<SignalRow> rows) {
        final int ast = observed(rows, "ROUTING_TOPOLOGY");
        final int lexical = observed(rows, "ROUTING_TEXT_CUE");
        if (ast <= 0 && lexical <= 0) return null;
        return candidate(
                path,
                owner,
                method,
                "eip:route-dag",
                Math.max(ast, lexical),
                ast > 0 ? "AST_INVOCATION" : "MASKED_REGEX_CUE",
                evidence(rows, "ROUTING_TOPOLOGY", "ROUTING_TEXT_CUE", "CONTRACT_"));
    }

    private static CandidateRow decompositionCandidate(
            final String path,
            final String owner,
            final String method,
            final List<SignalRow> rows) {
        final int statements = observed(rows, "LONG_METHOD");
        final int depth = observed(rows, "DEEP_CONTROL_NESTING");
        if (statements <= 0 || depth <= 0) return null;
        return candidate(
                path,
                owner,
                method,
                "m3:decompose-method",
                statements + depth,
                "AST_STRUCTURAL",
                evidence(rows, "LONG_METHOD", "DEEP_CONTROL_NESTING", "CONTRACT_"));
    }

    private static CandidateRow repeatedAtomCandidate(
            final String path,
            final String owner,
            final String method,
            final List<SignalRow> rows) {
        final int repeated = observed(rows, "REPEATED_LOGIC_SHAPE");
        if (repeated < 3) return null;
        return candidate(
                path,
                owner,
                method,
                "m3:extract-repeated-atom",
                repeated,
                "AST_NORMALIZED_SHAPE",
                evidence(rows, "REPEATED_LOGIC_SHAPE", "CONTRACT_"));
    }

    private static CandidateRow candidate(
            final String path,
            final String owner,
            final String method,
            final String pattern,
            final int score,
            final String evidenceClass,
            final List<String> evidence) {
        final String evidenceRoot = digest(
                "M3_PATTERN_EVIDENCE_V1",
                concat(List.of(path, owner, method, pattern, evidenceClass), evidence));
        return new CandidateRow(
                path,
                owner,
                method,
                pattern,
                score,
                evidenceClass,
                evidenceRoot,
                "CANDIDATE_ONLY",
                false,
                false);
    }

    private static List<ResidueRow> classifyResidue(
            final SourceContext source,
            final List<SignalRow> signals,
            final List<CandidateRow> candidates) {
        final ArrayList<ResidueRow> result = new ArrayList<>();
        for (CandidateRow candidate : candidates) {
            final List<SignalRow> methodSignals = signals.stream()
                    .filter(row -> row.owner().equals(candidate.owner())
                            && row.method().equals(candidate.method()))
                    .toList();
            final String risk = risk(candidate, methodSignals);
            if (!"PRIVATE_FILE_LOCAL_CANDIDATE".equals(risk)) {
                result.add(
                        new ResidueRow(
                                source.path(),
                                candidate.owner(),
                                candidate.method(),
                                candidate.patternCandidate(),
                                risk,
                                candidate.evidenceRoot(),
                                "REVIEW_REQUIRED",
                                false,
                                false));
            }
        }

        final Set<String> mapped =
                candidates.stream()
                        .flatMap(candidate -> signals.stream()
                                .filter(row -> row.owner().equals(candidate.owner())
                                        && row.method().equals(candidate.method()))
                                .map(SignalRow::signal))
                        .collect(java.util.stream.Collectors.toSet());
        signals.stream()
                .filter(row -> pressure(row.signal()) && !mapped.contains(row.signal()))
                .sorted(SignalRow.ORDER)
                .forEach(row ->
                        result.add(
                                new ResidueRow(
                                        row.sourcePath(),
                                        row.owner(),
                                        row.method(),
                                        "<none>",
                                        "UNMAPPED_PRESSURE_SIGNAL:" + row.signal(),
                                        row.evidenceRoot(),
                                        "TYPED_RESIDUE",
                                        false,
                                        false)));
        result.sort(ResidueRow.ORDER);
        return List.copyOf(result);
    }

    private static String risk(
            final CandidateRow candidate,
            final List<SignalRow> rows) {
        if ("MASKED_REGEX_CUE".equals(candidate.evidenceClass())) {
            return "LEXICAL_ONLY_NO_SEMANTIC_AUTHORITY";
        }
        if (present(rows, "CONTRACT_NATIVE")) {
            return "NATIVE_CONTRACT_HIGH";
        }
        if ((present(rows, "CONTRACT_PUBLIC") || present(rows, "CONTRACT_PROTECTED"))
                && effectful(rows)) {
            return "PUBLIC_EFFECTFUL_CONTRACT_HIGH";
        }
        if (present(rows, "EFFECT_SYNCHRONIZATION")
                || present(rows, "EFFECT_REFLECTION")
                || present(rows, "EFFECT_IO_LIFECYCLE")) {
            return "EFFECTFUL_REVIEW_REQUIRED";
        }
        if (present(rows, "CONTRACT_PRIVATE")) {
            return "PRIVATE_FILE_LOCAL_CANDIDATE";
        }
        return "REVIEW_REQUIRED";
    }

    private static boolean effectful(final List<SignalRow> rows) {
        return rows.stream().anyMatch(row ->
                row.signal().startsWith("EFFECT_")
                        || "CONSTRUCTION_FANOUT".equals(row.signal())
                        || "LISTENER_FANOUT".equals(row.signal())
                        || "ROUTING_TOPOLOGY".equals(row.signal()));
    }

    private static boolean pressure(final String signal) {
        return Set.of(
                        "GOD_CLASS_METHOD_DENSITY",
                        "WIDE_PARAMETER_SURFACE",
                        "LOCAL_STATE_PRESSURE",
                        "LONG_METHOD",
                        "DEEP_CONTROL_NESTING",
                        "CONTROL_BRANCH_POINTS",
                        "LOOP_DENSITY",
                        "REPEATED_LOGIC_SHAPE")
                .contains(signal);
    }

    private static int observed(final List<SignalRow> rows, final String signal) {
        return rows.stream()
                .filter(row -> row.signal().equals(signal))
                .mapToInt(SignalRow::observed)
                .max()
                .orElse(0);
    }

    private static boolean present(final List<SignalRow> rows, final String signal) {
        return rows.stream().anyMatch(row -> row.signal().equals(signal));
    }

    private static List<String> evidence(
            final List<SignalRow> rows,
            final String... prefixes) {
        return rows.stream()
                .filter(row -> {
                    for (String prefix : prefixes) {
                        if (prefix.endsWith("_")) {
                            if (row.signal().startsWith(prefix)) return true;
                        } else if (row.signal().equals(prefix)) {
                            return true;
                        }
                    }
                    return false;
                })
                .map(SignalRow::canonical)
                .sorted()
                .toList();
    }

    private static String normalized(final J.CompilationUnit unit) {
        final String value =
                unit.getSourcePath().normalize().toString().replace('\\', '/');
        if (value.isBlank()
                || value.startsWith("/")
                || value.startsWith("../")
                || value.contains("/../")
                || value.indexOf('\0') >= 0) {
            throw new IllegalArgumentException("invalid signal-chain source path: " + value);
        }
        return value;
    }

    private static String token(final String value, final String field) {
        final String checked = Objects.toString(value, "").strip();
        if (checked.isEmpty()
                || checked.length() > 4096
                || checked.indexOf('\0') >= 0
                || checked.indexOf('\r') >= 0
                || checked.indexOf('\n') >= 0) {
            throw new IllegalArgumentException(field);
        }
        return checked;
    }

    @SafeVarargs
    private static List<String> concat(final List<String>... parts) {
        final ArrayList<String> values = new ArrayList<>();
        for (List<String> part : parts) {
            values.addAll(part);
        }
        return List.copyOf(values);
    }

    private static String sha256(final String value) {
        return digest("M3_SOURCE_TEXT_V1", List.of(value));
    }

    private static String digest(final String domain, final List<String> values) {
        try {
            final MessageDigest digest = MessageDigest.getInstance("SHA-256");
            frame(digest, domain);
            for (String value : values) {
                frame(digest, value);
            }
            return java.util.HexFormat.of().formatHex(digest.digest());
        } catch (NoSuchAlgorithmException impossible) {
            throw new AssertionError(impossible);
        }
    }

    private static void frame(final MessageDigest digest, final String value) {
        final byte[] bytes = Objects.requireNonNull(value, "value").getBytes(StandardCharsets.UTF_8);
        digest.update((byte) (bytes.length >>> 24));
        digest.update((byte) (bytes.length >>> 16));
        digest.update((byte) (bytes.length >>> 8));
        digest.update((byte) bytes.length);
        digest.update(bytes);
    }

    private interface SignalHandler {
        String id();

        List<SignalRow> signals(SourceContext source);
    }

    @FunctionalInterface
    private interface CandidateRecognizer {
        CandidateRow recognize(String path, String owner, String method, List<SignalRow> signals);
    }

    private static final class StructuralHandler implements SignalHandler {
        @Override
        public String id() {
            return "STRUCTURAL";
        }

        @Override
        public List<SignalRow> signals(final SourceContext source) {
            final ArrayList<SignalRow> rows = new ArrayList<>();
            for (ClassFact type : source.classes()) {
                if (type.methodCount() > M3CodeSignalThresholds.MAX_METHODS_PER_TYPE) {
                    rows.add(signal(
                            source.path(),
                            type.owner(),
                            "<type>",
                            id(),
                            "GOD_CLASS_METHOD_DENSITY",
                            type.methodCount(),
                            M3CodeSignalThresholds.MAX_METHODS_PER_TYPE,
                            "AST_CLASS_STRUCTURE"));
                }
            }
            for (MethodFact method : source.methods()) {
                addIfAbove(rows, source.path(), method, id(), "WIDE_PARAMETER_SURFACE",
                        method.parameters(), M3CodeSignalThresholds.MAX_DIRECT_PARAMETERS);
                addIfAbove(rows, source.path(), method, id(), "LOCAL_STATE_PRESSURE",
                        method.locals(), M3CodeSignalThresholds.MAX_LOCAL_VARIABLES);
                addIfAbove(rows, source.path(), method, id(), "LONG_METHOD",
                        method.statements(), M3CodeSignalThresholds.MAX_STATEMENTS);
                if (method.lambdas() > 1) {
                    rows.add(signal(
                            source.path(),
                            method.owner(),
                            method.method(),
                            id(),
                            "LAMBDA_DENSITY",
                            method.lambdas(),
                            1,
                            "AST_METHOD_STRUCTURE"));
                }
                if (method.repeatedShapes() >= 3) {
                    rows.add(signal(
                            source.path(),
                            method.owner(),
                            method.method(),
                            id(),
                            "REPEATED_LOGIC_SHAPE",
                            method.repeatedShapes(),
                            2,
                            "AST_NORMALIZED_SHAPE"));
                }
            }
            rows.sort(SignalRow.ORDER);
            return List.copyOf(rows);
        }
    }

    private static final class ControlFlowHandler implements SignalHandler {
        @Override
        public String id() {
            return "CONTROL_FLOW";
        }

        @Override
        public List<SignalRow> signals(final SourceContext source) {
            final ArrayList<SignalRow> rows = new ArrayList<>();
            for (MethodFact method : source.methods()) {
                addIfAbove(rows, source.path(), method, id(), "DEEP_CONTROL_NESTING",
                        method.maxDepth(), M3CodeSignalThresholds.MAX_NESTING_DEPTH);
                addIfAbove(rows, source.path(), method, id(), "CONTROL_BRANCH_POINTS",
                        method.branches(), M3CodeSignalThresholds.MAX_BRANCH_POINTS);
                if (method.loops() > 2) {
                    rows.add(signal(
                            source.path(),
                            method.owner(),
                            method.method(),
                            id(),
                            "LOOP_DENSITY",
                            method.loops(),
                            2,
                            "AST_CONTROL_FLOW"));
                }
                if (method.switches() > 0) {
                    rows.add(signal(
                            source.path(),
                            method.owner(),
                            method.method(),
                            id(),
                            "SWITCH_PRESENT",
                            method.switches(),
                            0,
                            "AST_CONTROL_FLOW"));
                }
                if (method.tryCount() + method.catches() > 1) {
                    rows.add(signal(
                            source.path(),
                            method.owner(),
                            method.method(),
                            id(),
                            "TRY_CATCH_DENSITY",
                            method.tryCount() + method.catches(),
                            1,
                            "AST_CONTROL_FLOW"));
                }
            }
            rows.sort(SignalRow.ORDER);
            return List.copyOf(rows);
        }
    }

    private static final class EffectContractHandler implements SignalHandler {
        @Override
        public String id() {
            return "EFFECT_CONTRACT";
        }

        @Override
        public List<SignalRow> signals(final SourceContext source) {
            final ArrayList<SignalRow> rows = new ArrayList<>();
            for (MethodFact method : source.methods()) {
                rows.add(signal(
                        source.path(),
                        method.owner(),
                        method.method(),
                        id(),
                        "CONTRACT_" + method.contractSurface(),
                        1,
                        0,
                        "AST_MODIFIER_SURFACE"));
                addPositive(rows, source.path(), method, id(), "EFFECT_FIELD_WRITE",
                        method.fieldWrites(), "AST_EFFECT");
                addPositive(rows, source.path(), method, id(), "EFFECT_SYNCHRONIZATION",
                        method.synchronization(), "AST_EFFECT");
                addPositive(rows, source.path(), method, id(), "EFFECT_IO_LIFECYCLE",
                        method.ioCalls(), "AST_INVOCATION");
                addPositive(rows, source.path(), method, id(), "EFFECT_REFLECTION",
                        method.reflectionCalls(), "AST_INVOCATION");
                if (method.constructorCalls() >= 3) {
                    rows.add(signal(
                            source.path(),
                            method.owner(),
                            method.method(),
                            id(),
                            "CONSTRUCTION_FANOUT",
                            method.constructorCalls(),
                            2,
                            "AST_CONSTRUCTION"));
                }
                if (method.listenerCalls() >= 2) {
                    rows.add(signal(
                            source.path(),
                            method.owner(),
                            method.method(),
                            id(),
                            "LISTENER_FANOUT",
                            method.listenerCalls(),
                            1,
                            "AST_INVOCATION"));
                }
                addPositive(rows, source.path(), method, id(), "ROUTING_TOPOLOGY",
                        method.routeCalls(), "AST_INVOCATION");
            }
            rows.sort(SignalRow.ORDER);
            return List.copyOf(rows);
        }
    }

    private static final class MaskedRegexHandler implements SignalHandler {
        private static final List<LexicalCue> CUES = List.of(
                cue(
                        "OBSERVER_TEXT_CUE",
                        "\\b(?:add[A-Za-z0-9_$]*Listener|subscribe|observe)\\s*\\(",
                        "gof:observer"),
                cue(
                        "ROUTING_TEXT_CUE",
                        "\\b(?:route|from|to|choice|when|otherwise|split|aggregate|multicast|"
                                + "recipientList|routingSlip|serviceCall)\\s*\\(",
                        "eip:route-dag"),
                cue(
                        "CONSTRUCTION_TEXT_CUE",
                        "\\bnew\\s+[A-Za-z_$][A-Za-z0-9_$.]*\\s*\\(",
                        "gof:factory-method"));

        @Override
        public String id() {
            return "MASKED_REGEX";
        }

        @Override
        public List<SignalRow> signals(final SourceContext source) {
            final ArrayList<SignalRow> rows = new ArrayList<>();
            for (LexicalCue cue : CUES) {
                int count = 0;
                final Matcher matcher = cue.pattern().matcher(source.maskedSource());
                while (matcher.find() && count < 10_000) {
                    count++;
                }
                if (count > 0) {
                    rows.add(
                            signal(
                                    source.path(),
                                    "<file>",
                                    "<lexical>",
                                    id(),
                                    cue.signal(),
                                    count,
                                    0,
                                    "MASKED_REGEX_NOMINATION_ONLY:" + cue.patternCandidate()));
                }
            }
            rows.sort(SignalRow.ORDER);
            return List.copyOf(rows);
        }

        private static LexicalCue cue(
                final String signal, final String regex, final String candidate) {
            return new LexicalCue(
                    signal,
                    Pattern.compile(regex),
                    candidate);
        }
    }

    private static void addIfAbove(
            final List<SignalRow> rows,
            final String path,
            final MethodFact method,
            final String handler,
            final String signal,
            final int observed,
            final int threshold) {
        if (observed > threshold) {
            rows.add(signal(
                    path,
                    method.owner(),
                    method.method(),
                    handler,
                    signal,
                    observed,
                    threshold,
                    "AST_STRUCTURAL"));
        }
    }

    private static void addPositive(
            final List<SignalRow> rows,
            final String path,
            final MethodFact method,
            final String handler,
            final String signal,
            final int observed,
            final String detail) {
        if (observed > 0) {
            rows.add(signal(
                    path,
                    method.owner(),
                    method.method(),
                    handler,
                    signal,
                    observed,
                    0,
                    detail));
        }
    }

    private static SignalRow signal(
            final String path,
            final String owner,
            final String method,
            final String handler,
            final String signal,
            final int observed,
            final int threshold,
            final String detail) {
        final String evidenceRoot =
                digest(
                        "M3_SIGNAL_ROW_V1",
                        List.of(
                                path,
                                owner,
                                method,
                                handler,
                                signal,
                                Integer.toString(observed),
                                Integer.toString(threshold),
                                detail));
        return new SignalRow(
                path,
                owner,
                method,
                handler,
                signal,
                observed,
                threshold,
                detail,
                evidenceRoot,
                "CANDIDATE_ONLY",
                false,
                false);
    }

    private static final class MethodFact {
        private final String owner;
        private final String method;
        private final String contractSurface;
        private final int parameters;
        private int locals;
        private int statements;
        private int maxDepth;
        private int branches;
        private int loops;
        private int switches;
        private int tryCount;
        private int catches;
        private int lambdas;
        private int constructorCalls;
        private int listenerCalls;
        private int routeCalls;
        private int fieldWrites;
        private int synchronization;
        private int ioCalls;
        private int reflectionCalls;
        private int repeatedShapes;

        private MethodFact(
                final String owner,
                final String method,
                final String contractSurface,
                final int parameters) {
            this.owner = owner;
            this.method = method;
            this.contractSurface = contractSurface;
            this.parameters = parameters;
        }

        static MethodFact of(
                final String owner,
                final J.MethodDeclaration method) {
            final MethodFact fact =
                    new MethodFact(
                            owner,
                            method.getSimpleName(),
                            M3AtomPatternSignalChainRecipe.contractSurface(method),
                            method.getParameters().size());
            if (method.getBody() == null) {
                return fact;
            }

            final Map<String, Integer> shapes = new HashMap<>();
            new JavaIsoVisitor<MethodFact>() {
                private int depth;

                @Override
                public J.Block visitBlock(final J.Block block, final MethodFact value) {
                    value.statements += block.getStatements().size();
                    for (J statement : block.getStatements()) {
                        shapes.merge(statementShape(statement), 1, Integer::sum);
                    }
                    return super.visitBlock(block, value);
                }

                @Override
                public J.ClassDeclaration visitClassDeclaration(
                        final J.ClassDeclaration type,
                        final MethodFact value) {
                    return type;
                }

                @Override
                public J.VariableDeclarations visitVariableDeclarations(
                        final J.VariableDeclarations declarations,
                        final MethodFact value) {
                    value.locals += declarations.getVariables().size();
                    return super.visitVariableDeclarations(declarations, value);
                }

                @Override
                public J.If visitIf(final J.If iff, final MethodFact value) {
                    value.branches++;
                    enter(value);
                    try {
                        return super.visitIf(iff, value);
                    } finally {
                        exit();
                    }
                }

                @Override
                public J.Switch visitSwitch(final J.Switch sw, final MethodFact value) {
                    value.switches++;
                    value.branches++;
                    enter(value);
                    try {
                        return super.visitSwitch(sw, value);
                    } finally {
                        exit();
                    }
                }

                @Override
                public J.SwitchExpression visitSwitchExpression(
                        final J.SwitchExpression sw, final MethodFact value) {
                    value.switches++;
                    value.branches++;
                    enter(value);
                    try {
                        return super.visitSwitchExpression(sw, value);
                    } finally {
                        exit();
                    }
                }

                @Override
                public J.Ternary visitTernary(final J.Ternary ternary, final MethodFact value) {
                    value.branches++;
                    return super.visitTernary(ternary, value);
                }

                @Override
                public J.ForLoop visitForLoop(final J.ForLoop loop, final MethodFact value) {
                    value.loops++;
                    enter(value);
                    try {
                        return super.visitForLoop(loop, value);
                    } finally {
                        exit();
                    }
                }

                @Override
                public J.ForEachLoop visitForEachLoop(
                        final J.ForEachLoop loop,
                        final MethodFact value) {
                    value.loops++;
                    enter(value);
                    try {
                        return super.visitForEachLoop(loop, value);
                    } finally {
                        exit();
                    }
                }

                @Override
                public J.WhileLoop visitWhileLoop(final J.WhileLoop loop, final MethodFact value) {
                    value.loops++;
                    enter(value);
                    try {
                        return super.visitWhileLoop(loop, value);
                    } finally {
                        exit();
                    }
                }

                @Override
                public J.DoWhileLoop visitDoWhileLoop(
                        final J.DoWhileLoop loop,
                        final MethodFact value) {
                    value.loops++;
                    enter(value);
                    try {
                        return super.visitDoWhileLoop(loop, value);
                    } finally {
                        exit();
                    }
                }

                @Override
                public J.Try visitTry(final J.Try tr, final MethodFact value) {
                    value.tryCount++;
                    value.catches += tr.getCatches().size();
                    enter(value);
                    try {
                        return super.visitTry(tr, value);
                    } finally {
                        exit();
                    }
                }

                @Override
                public J.Synchronized visitSynchronized(
                        final J.Synchronized sync,
                        final MethodFact value) {
                    value.synchronization++;
                    enter(value);
                    try {
                        return super.visitSynchronized(sync, value);
                    } finally {
                        exit();
                    }
                }

                @Override
                public J.Lambda visitLambda(final J.Lambda lambda, final MethodFact value) {
                    value.lambdas++;
                    return super.visitLambda(lambda, value);
                }

                @Override
                public J.NewClass visitNewClass(final J.NewClass creation, final MethodFact value) {
                    value.constructorCalls++;
                    return super.visitNewClass(creation, value);
                }

                @Override
                public J.Assignment visitAssignment(
                        final J.Assignment assignment,
                        final MethodFact value) {
                    if (isFieldWriteTarget(assignment.getVariable())) {
                        value.fieldWrites++;
                    }
                    return super.visitAssignment(assignment, value);
                }

                @Override
                public J.AssignmentOperation visitAssignmentOperation(
                        final J.AssignmentOperation assignment,
                        final MethodFact value) {
                    if (isFieldWriteTarget(assignment.getVariable())) {
                        value.fieldWrites++;
                    }
                    return super.visitAssignmentOperation(assignment, value);
                }

                @Override
                public J.Unary visitUnary(final J.Unary unary, final MethodFact value) {
                    if (unary.getOperator().isModifying() && isFieldWriteTarget(unary.getExpression())) {
                        value.fieldWrites++;
                    }
                    return super.visitUnary(unary, value);
                }

                @Override
                public J.MethodInvocation visitMethodInvocation(
                        final J.MethodInvocation invocation,
                        final MethodFact value) {
                    final String name = invocation.getSimpleName().toLowerCase(Locale.ROOT);
                    if ((name.startsWith("add")
                                    && (name.contains("listener")
                                            || name.contains("observer")
                                            || name.contains("subscriber")))
                            || Set.of("subscribe", "observe").contains(name)) {
                        value.listenerCalls++;
                    }
                    if (Set.of(
                                    "route",
                                    "from",
                                    "to",
                                    "tod",
                                    "choice",
                                    "when",
                                    "otherwise",
                                    "split",
                                    "aggregate",
                                    "multicast",
                                    "recipientlist",
                                    "routingslip",
                                    "servicecall")
                            .contains(name)) {
                        value.routeCalls++;
                    }
                    if (Set.of(
                                    "write",
                                    "save",
                                    "send",
                                    "delete",
                                    "close",
                                    "start",
                                    "stop",
                                    "commit",
                                    "rollback",
                                    "lock",
                                    "unlock",
                                    "publish",
                                    "notify",
                                    "execute",
                                    "submit")
                            .contains(name)) {
                        value.ioCalls++;
                    }
                    if (Set.of(
                                    "forname",
                                    "getdeclaredmethod",
                                    "getdeclaredfield",
                                    "getmethod",
                                    "getfield",
                                    "setaccessible",
                                    "invoke",
                                    "newinstance")
                            .contains(name)) {
                        value.reflectionCalls++;
                    }
                    return super.visitMethodInvocation(invocation, value);
                }

                private void enter(final MethodFact value) {
                    depth++;
                    value.maxDepth = Math.max(value.maxDepth, depth);
                }

                private void exit() {
                    depth--;
                }
            }.visit(method.getBody(), fact);

            fact.repeatedShapes =
                    shapes.values().stream().mapToInt(Integer::intValue).max().orElse(0);
            return fact;
        }

        private static boolean isFieldWriteTarget(final org.openrewrite.java.tree.Expression target) {
            if (target instanceof J.FieldAccess) return true;
            if (!(target instanceof J.Identifier identifier)) return false;
            final var variable = identifier.getFieldType();
            return variable != null
                    && variable.getOwner() instanceof org.openrewrite.java.tree.JavaType.FullyQualified;
        }

        String owner() { return owner; }
        String method() { return method; }
        String contractSurface() { return contractSurface; }
        int parameters() { return parameters; }
        int locals() { return locals; }
        int statements() { return statements; }
        int maxDepth() { return maxDepth; }
        int branches() { return branches; }
        int loops() { return loops; }
        int switches() { return switches; }
        int tryCount() { return tryCount; }
        int catches() { return catches; }
        int lambdas() { return lambdas; }
        int constructorCalls() { return constructorCalls; }
        int listenerCalls() { return listenerCalls; }
        int routeCalls() { return routeCalls; }
        int fieldWrites() { return fieldWrites; }
        int synchronization() { return synchronization; }
        int ioCalls() { return ioCalls; }
        int reflectionCalls() { return reflectionCalls; }
        int repeatedShapes() { return repeatedShapes; }
    }

    private static String statementShape(final J tree) {
        final ArrayList<String> tokens = new ArrayList<>();
        new JavaIsoVisitor<List<String>>() {
            @Override
            public J preVisit(final J value, final List<String> sink) {
                sink.add(value.getClass().getSimpleName());
                if (value instanceof J.Binary binary) {
                    sink.add("B:" + binary.getOperator());
                } else if (value instanceof J.Unary unary) {
                    sink.add("U:" + unary.getOperator());
                } else if (value instanceof J.AssignmentOperation assignment) {
                    sink.add("A:" + assignment.getOperator());
                } else if (value instanceof J.MethodInvocation invocation) {
                    sink.add("CALL:" + invocation.getArguments().size());
                } else if (value instanceof J.NewClass) {
                    sink.add("NEW");
                } else if (value instanceof J.Literal literal) {
                    sink.add("LITERAL:"
                            + (literal.getType() == null
                                    ? "UNKNOWN"
                                    : literal.getType().getClass().getSimpleName()));
                } else if (value instanceof J.Identifier identifier) {
                    sink.add("IDENT:"
                            + (identifier.getType() == null
                                    ? "UNKNOWN"
                                    : identifier.getType().getClass().getSimpleName()));
                }
                return super.preVisit(value, sink);
            }

            @Override
            public J.ClassDeclaration visitClassDeclaration(
                    final J.ClassDeclaration type,
                    final List<String> sink) {
                sink.add("NESTED_CLASS");
                return type;
            }
        }.visit(tree, tokens);
        return digest("M3_STATEMENT_SHAPE_V1", tokens);
    }

    private static String contractSurface(final J.MethodDeclaration method) {
        if (method.hasModifier(J.Modifier.Type.Native)) return "NATIVE";
        if (method.hasModifier(J.Modifier.Type.Public)) return "PUBLIC";
        if (method.hasModifier(J.Modifier.Type.Protected)) return "PROTECTED";
        if (method.hasModifier(J.Modifier.Type.Private)) return "PRIVATE";
        return "PACKAGE";
    }

    public static final class Inventory {
        private final Map<String, SourceAnalysis> analyses = new ConcurrentHashMap<>();

        synchronized void observe(final SourceAnalysis analysis) {
            final SourceAnalysis prior = analyses.putIfAbsent(analysis.path(), analysis);
            if (prior != null) {
                throw new IllegalStateException(
                        "duplicate M3 signal-chain source: " + analysis.path());
            }
        }

        List<SourceAnalysis> analyses() {
            return analyses.values().stream()
                    .sorted(Comparator.comparing(SourceAnalysis::path))
                    .toList();
        }
    }

