/**
 * File-local evidence chain behind M3CodeSignalTriggerRecipe. No source-writing authority.
 * The four recognizers read one source-bound snapshot and have private outputs/contexts.
 * Only the coordinator publishes after deterministic reduction and evidence fixed point.
 * Lexical edges and syntactic effects are not control-flow, dataflow or equivalence proofs.
 */
final class M3CodeSignalChain {
    static final String LIMITS_KEY = "com.synexia.m3.signalChain.limits";
    // Reuse the existing source-visibility ProgressMonitor adaptation contract.
    static final String CANCELED_KEY = "com.synexia.m3.sourceVisibility.canceled";
    static final String WORKED_KEY = "com.synexia.m3.sourceVisibility.worked";
    private static final String VERSION = "M3-SIGNAL-CHAIN/1";

    enum Stage {
        INVENTORY, STRUCTURE, CONTROL_FLOW, EFFECT_CONTRACT, MASKED_CUES,
        CANDIDATES, CONTRACT_RISK, FIXED_POINT
    }

    enum Status {
        COMPLETE_EVIDENCE_ONLY, PASS_BUDGET_EXHAUSTED, SOURCE_BUDGET_EXHAUSTED,
        NODE_BUDGET_EXHAUSTED, SIGNAL_BUDGET_EXHAUSTED, CANCELED,
        INVALID_AST, MASK_MISMATCH, HANDLER_FAILURE, CONFLICTING_EVIDENCE
    }

    record Limits(int passes, int sourceChars, int nodes, int signals, int workers) {
        Limits {
            if (passes < 1 || passes > 8 || sourceChars < 1 || sourceChars > 2_000_000
                    || nodes < 1 || nodes > 1_000_000 || signals < 1 || signals > 1_000_000
                    || workers < 1 || workers > 8) throw new IllegalArgumentException("signal limits");
        }
        static Limits defaults() { return new Limits(2, 2_000_000, 200_000, 100_000, 4); }
    }

    record Signal(Stage stage, String subject, String code, int observed, String target) {
        Signal {
            Objects.requireNonNull(stage, "stage");
            Objects.requireNonNull(subject, "subject");
            Objects.requireNonNull(code, "code");
            Objects.requireNonNull(target, "target");
            if (subject.isEmpty() || code.isEmpty() || observed < 0) {
                throw new IllegalArgumentException("signal");
            }
        }
        String key() { return SealHash.frame(stage.name(), subject, code); }
        String root() { return SealHash.frame(key(), Integer.toString(observed), target); }
    }

    record StageReceipt(Stage stage, List<Stage> parents, String root, int signals) {
        StageReceipt { parents = List.copyOf(parents); SealHash.require(root); }
    }

    record Report(String sourcePath, String sourceSha256, Status status, int passes,
                  String root, List<StageReceipt> stages, List<Signal> signals,
                  List<SignalRow> legacyRows, List<String> residue) {
        Report {
            stages = List.copyOf(stages);
            signals = List.copyOf(signals);
            legacyRows = List.copyOf(legacyRows);
            residue = List.copyOf(residue);
            if (status == Status.COMPLETE_EVIDENCE_ONLY) SealHash.require(root);
            else if (!root.isEmpty() || !stages.isEmpty() || !signals.isEmpty() || !legacyRows.isEmpty()) {
                throw new IllegalArgumentException("incomplete chain cannot publish a success prefix");
            }
        }
        boolean complete() { return status == Status.COMPLETE_EVIDENCE_ONLY; }
        boolean mutationAuthority() { return false; }
        boolean promotionAuthority() { return false; }
    }

    @FunctionalInterface
    interface StructuralScanner {
        List<SignalRow> scan(J.CompilationUnit unit, ExecutionContext context);
    }

    private record Snapshot(J.CompilationUnit unit, String sourcePath, String sourceSha256,
                            String masked, Map<String, Integer> counts,
                            Map<String, Integer> repeatedBodies, int nodes) { }
    private record Contribution(Stage stage, List<Signal> signals, List<SignalRow> legacyRows) {
        Contribution { signals = List.copyOf(signals); legacyRows = List.copyOf(legacyRows); }
    }
    private static final List<Stage> RECOGNIZERS = List.of(
            Stage.STRUCTURE, Stage.CONTROL_FLOW, Stage.EFFECT_CONTRACT, Stage.MASKED_CUES);

    private M3CodeSignalChain() { }

    static TreeVisitor<?, ExecutionContext> visitor(Recipe owner, StructuralScanner scanner,
                                                   BiConsumer<ExecutionContext, SignalRow> publish) {
        ReceiptTable receiptTable = new ReceiptTable(owner);
        EvidenceTable evidenceTable = new EvidenceTable(owner);
        DagTable dagTable = new DagTable(owner);
        return new TreeVisitor<Tree, ExecutionContext>() {
            @Override public Tree preVisit(Tree tree, ExecutionContext context) {
                if (!(tree instanceof SourceFile source)) return tree;
                stopAfterPreVisit();
                Limits limits = context.getMessage(LIMITS_KEY, Limits.defaults());
                BooleanSupplier canceled = context.getMessage(CANCELED_KEY);
                LongConsumer worked = context.getMessage(WORKED_KEY);
                Report report = analyze(source, scanner, limits, canceled, worked, RECOGNIZERS);
                receiptTable.insertRow(context, new ReceiptRow(report.sourcePath(), report.sourceSha256(),
                        report.status().name(), report.passes(), report.root(), report.signals().size(),
                        String.join(",", report.residue()), false, false));
                if (report.complete()) {
                    report.signals().forEach(signal -> evidenceTable.insertRow(context,
                            new EvidenceRow(report.sourcePath(), report.sourceSha256(), signal.stage().name(),
                                    signal.subject(), signal.code(), signal.observed(), signal.target(), signal.root())));
                    report.stages().forEach(stage -> dagTable.insertRow(context,
                            new DagRow(report.sourcePath(), stage.stage().name(),
                                    String.join(",", stage.parents().stream().map(Enum::name).toList()), stage.root(), stage.signals())));
                    report.legacyRows().forEach(row -> publish.accept(context, row));
                } else {
                    context.getOnError().accept(new IllegalStateException("M3 signal chain: " + report.status()));
                }
                return source;
            }
        };
    }

    static Report analyze(SourceFile source, StructuralScanner scanner, Limits limits,
                          BooleanSupplier canceled, LongConsumer worked) {
        return analyze(source, scanner, limits, canceled, worked, RECOGNIZERS);
    }

    // Recognition order is injectable only inside this package to prove scheduling independence.
    static Report analyze(SourceFile source, StructuralScanner scanner, Limits limits,
                          BooleanSupplier canceled, LongConsumer worked, List<Stage> order) {
        Objects.requireNonNull(source, "source");
        Objects.requireNonNull(scanner, "scanner");
        Objects.requireNonNull(limits, "limits");
        if (order.size() != RECOGNIZERS.size() || !Set.copyOf(order).equals(Set.copyOf(RECOGNIZERS))) {
            throw new IllegalArgumentException("recognizer coverage");
        }
        String path = source.getSourcePath().normalize().toString().replace('\\', '/');
        String sourceHash = "";
        Runnable checkpoint = () -> checkCanceled(canceled);
        int passes = 0;
        try {
            checkpoint.run();
            if (!(source instanceof J.CompilationUnit unit)) throw new Refusal(Status.INVALID_AST);
            String text = unit.printAll();
            if (text.length() > limits.sourceChars()) throw new Refusal(Status.SOURCE_BUDGET_EXHAUSTED);
            sourceHash = SealHash.text(text);
            Snapshot snapshot = snapshot(unit, path, sourceHash, text, limits, checkpoint);
            EnumMap<Stage, Contribution> contributions = recognize(snapshot, scanner, limits, canceled, order);
            checkpoint.run();
            contributions.put(Stage.INVENTORY, new Contribution(Stage.INVENTORY,
                    List.of(new Signal(Stage.INVENTORY, "<file>", "LST_NODES", snapshot.nodes(), "READ_ONLY")), List.of()));
            contributions.put(Stage.CANDIDATES, candidates(contributions, snapshot));
            contributions.put(Stage.CONTRACT_RISK, risks(contributions));

            // Independent facts are immutable. Replaying their join must reach quiescence;
            // this is an evidence fixed point, not proof of a source-transform fixed point.
            Map<String, Signal> accumulated = Map.of();
            for (passes = 1; passes <= limits.passes(); passes++) {
                checkpoint.run();
                List<Signal> next = new ArrayList<>(accumulated.values());
                for (Stage stage : Stage.values()) {
                    Contribution contribution = contributions.get(stage);
                    if (contribution != null) next.addAll(contribution.signals());
                }
                Map<String, Signal> joined = join(next, limits.signals());
                if (worked != null) worked.accept(1L); // coordinator only, never worker callbacks
                if (joined.equals(accumulated)) {
                    contributions.put(Stage.FIXED_POINT, new Contribution(Stage.FIXED_POINT,
                            List.of(new Signal(Stage.FIXED_POINT, "<file>", "EVIDENCE_QUIESCENT", 1, "NO_PROMOTION")), List.of()));
                    List<Signal> terminal = new ArrayList<>(joined.values());
                    terminal.addAll(contributions.get(Stage.FIXED_POINT).signals());
                    Map<String, Signal> completeSignals = join(terminal, limits.signals());
                    List<StageReceipt> receipts = receipts(contributions, sourceHash, path);
                    List<SignalRow> rows = RECOGNIZERS.stream()
                            .flatMap(stage -> contributions.get(stage).legacyRows().stream()).toList();
                    List<String> residue = contributions.get(Stage.CONTRACT_RISK).signals().stream()
                            .map(Signal::code).distinct().sorted().toList();
                    checkpoint.run();
                    return new Report(path, sourceHash, Status.COMPLETE_EVIDENCE_ONLY, passes,
                            receipts.getLast().root(), receipts, List.copyOf(completeSignals.values()), rows, residue);
                }
                accumulated = joined;
            }
            return failed(path, sourceHash, Status.PASS_BUDGET_EXHAUSTED, limits.passes());
        } catch (Refusal refusal) {
            return failed(path, sourceHash, refusal.status, Math.min(passes, limits.passes()));
        } catch (RuntimeException failure) {
            return failed(path, sourceHash, failureStatus(failure), Math.min(passes, limits.passes()));
        }
    }

    private static Status failureStatus(Throwable failure) {
        // OpenRewrite wraps visitor exceptions. Preserve bounded/cancellation residue
        // rather than accidentally reclassifying it as an unknown handler failure.
        for (int depth = 0; failure != null && depth < 32; depth++, failure = failure.getCause()) {
            if (failure instanceof Refusal refusal) return refusal.status;
        }
        return Status.HANDLER_FAILURE;
    }

    private static Report failed(String path, String hash, Status status, int passes) {
        return new Report(path, hash, status, passes, "", List.of(), List.of(), List.of(), List.of(status.name()));
    }

    static void checkpoint(ExecutionContext context) {
        checkCanceled(context.getMessage(CANCELED_KEY));
    }

    private static void checkCanceled(BooleanSupplier canceled) {
        if (Thread.currentThread().isInterrupted() || canceled != null && canceled.getAsBoolean()) {
            throw new Refusal(Status.CANCELED);
        }
    }

    private static Snapshot snapshot(J.CompilationUnit unit, String path, String hash, String text,
                                     Limits limits, Runnable checkpoint) {
        Map<String, Integer> counts = new TreeMap<>();
        Map<String, Integer> bodies = new TreeMap<>();
        int[] nodes = {0};
        new JavaIsoVisitor<Void>() {
            @Override public J preVisit(J tree, Void unused) {
                checkpoint.run();
                if (++nodes[0] > limits.nodes()) throw new Refusal(Status.NODE_BUDGET_EXHAUSTED);
                if (tree instanceof J.Unknown
                        || tree.getMarkers().findFirst(ParseExceptionResult.class).isPresent()) {
                    throw new Refusal(Status.INVALID_AST);
                }
                counts.merge(tree.getClass().getSimpleName(), 1, Integer::sum);
                return tree;
            }
            @Override public J.MethodDeclaration visitMethodDeclaration(J.MethodDeclaration method, Void unused) {
                if (method.hasModifier(J.Modifier.Type.Native)) counts.merge("NativeMethod", 1, Integer::sum);
                if (method.hasModifier(J.Modifier.Type.Synchronized)) counts.merge("Synchronized", 1, Integer::sum);
                if (method.getBody() != null) {
                    String body = method.getBody().printTrimmed(getCursor());
                    bodies.merge(SealHash.text(body), 1, Integer::sum);
                }
                return super.visitMethodDeclaration(method, unused);
            }
            @Override public J.MethodInvocation visitMethodInvocation(J.MethodInvocation call, Void unused) {
                if (!TypeUtils.isWellFormedType(call.getMethodType())) counts.merge("UnresolvedCall", 1, Integer::sum);
                return super.visitMethodInvocation(call, unused);
            }
            @Override public J.Unary visitUnary(J.Unary unary, Void unused) {
                switch (unary.getOperator()) {
                    case PreIncrement, PreDecrement, PostIncrement, PostDecrement ->
                            counts.merge("IncrementDecrement", 1, Integer::sum);
                    default -> { }
                }
                return super.visitUnary(unary, unused);
            }
        }.visit(unit, null);
        String masked = maskedSource(unit, checkpoint);
        if (masked.length() != text.length()) throw new Refusal(Status.MASK_MISMATCH);
        for (int i = 0; i < text.length(); i++) {
            if ((i & 1023) == 0) checkpoint.run();
            char a = text.charAt(i), b = masked.charAt(i);
            if (a == '\n' || a == '\r' || b == '\n' || b == '\r') {
                if (a != b) throw new Refusal(Status.MASK_MISMATCH);
            }
        }
        return new Snapshot(unit, path, hash, masked, Map.copyOf(counts), Map.copyOf(bodies), nodes[0]);
    }

    /**
     * The existing LST printer defines lexical regions; no regex lexer is introduced.
     * Encoded comments may occupy whitespace or comment suffixes in the pinned parser,
     * so all trivia is blanked along with comments and literal payloads.
     */
    static String maskedSource(J.CompilationUnit unit, Runnable checkpoint) {
        PrintOutputCapture<Void> out = new PrintOutputCapture<>(null);
        new JavaPrinter<Void>() {
            @Override public Space visitSpace(Space space, Space.Location location, PrintOutputCapture<Void> p) {
                checkpoint.run();
                p.append(blank(space.getWhitespace(), checkpoint));
                for (Comment comment : space.getComments()) {
                    p.append(blank(comment.printComment(getCursor()), checkpoint));
                    p.append(blank(comment.getSuffix(), checkpoint));
                }
                return space;
            }
            @Override public J visitLiteral(J.Literal literal, PrintOutputCapture<Void> p) {
                checkpoint.run();
                if (literal.getValue() instanceof String || literal.getValue() instanceof Character) {
                    PrintOutputCapture<Void> buffer = new PrintOutputCapture<>(null);
                    super.visitLiteral(literal, buffer);
                    p.append(blank(buffer.getOut(), checkpoint));
                    return literal;
                }
                return super.visitLiteral(literal, p);
            }
        }.visit(unit, out);
        return out.getOut();
    }

    private static String blank(String text, Runnable checkpoint) {
        char[] chars = text.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            if ((i & 1023) == 0) checkpoint.run();
            if (chars[i] != '\n' && chars[i] != '\r') chars[i] = ' ';
        }
        return new String(chars);
    }

    private static EnumMap<Stage, Contribution> recognize(Snapshot snapshot, StructuralScanner scanner,
                                                         Limits limits, BooleanSupplier canceled,
                                                         List<Stage> order) {
        EnumMap<Stage, Future<Contribution>> futures = new EnumMap<>(Stage.class);
        EnumMap<Stage, Contribution> complete = new EnumMap<>(Stage.class);
        try (ExecutorService executor = Executors.newFixedThreadPool(limits.workers())) {
            for (Stage stage : order) {
                Callable<Contribution> work = () -> {
                    checkCanceled(canceled);
                    Contribution result = switch (stage) {
                        case STRUCTURE -> structural(snapshot, scanner, canceled);
                        case CONTROL_FLOW -> counts(stage, snapshot, List.of("ForLoop", "ForEachLoop",
                                "WhileLoop", "DoWhileLoop", "If", "Switch", "SwitchExpression",
                                "Break", "Continue", "Return", "Throw", "Yield", "Label"), "CONTROL_REGION_REVIEW");
                        case EFFECT_CONTRACT -> counts(stage, snapshot, List.of("Assignment", "AssignmentOperation",
                                "IncrementDecrement", "Synchronized", "Try", "Lambda", "NewClass", "NativeMethod",
                                "UnresolvedCall"), "EFFECT_CONTRACT_REVIEW");
                        case MASKED_CUES -> lexical(snapshot);
                        default -> throw new IllegalArgumentException("not independent recognizer");
                    };
                    checkCanceled(canceled);
                    return result;
                };
                futures.put(stage, executor.submit(work));
            }
            try {
                // Canonical dependency/handler order, never completion or hash-table order.
                for (Stage stage : RECOGNIZERS) complete.put(stage, futures.get(stage).get());
            } catch (InterruptedException interrupted) {
                Thread.currentThread().interrupt();
                throw new Refusal(Status.CANCELED);
            } catch (ExecutionException failure) {
                Throwable cause = failure.getCause();
                if (cause instanceof Error error) throw error;
                throw new Refusal(failureStatus(cause));
            } finally {
                futures.values().forEach(future -> future.cancel(true));
                executor.shutdownNow();
            }
        }
        return complete;
    }

    private static Contribution structural(Snapshot snapshot, StructuralScanner scanner, BooleanSupplier canceled) {
        List<Throwable> errors = new ArrayList<>();
        InMemoryExecutionContext isolated = new InMemoryExecutionContext(errors::add);
        if (canceled != null) isolated.putMessage(CANCELED_KEY, canceled);
        List<SignalRow> rows = List.copyOf(scanner.scan(snapshot.unit(), isolated));
        if (!errors.isEmpty()) throw new Refusal(Status.HANDLER_FAILURE);
        List<Signal> signals = new ArrayList<>();
        for (int i = 0; i < rows.size(); i++) {
            SignalRow row = rows.get(i);
            if (!"CANDIDATE_ONLY".equals(row.authority()) || !snapshot.sourcePath().equals(row.sourcePath())) {
                throw new Refusal(Status.CONFLICTING_EVIDENCE);
            }
            signals.add(new Signal(Stage.STRUCTURE, row.owner() + "/" + row.method() + "/" + i,
                    row.signal(), row.observed(), row.nextHandler() + ":" + row.patternCandidate()));
        }
        return new Contribution(Stage.STRUCTURE, signals, rows);
    }

    private static Contribution counts(Stage stage, Snapshot snapshot, List<String> names, String target) {
        List<Signal> signals = names.stream().filter(name -> snapshot.counts().containsKey(name))
                .map(name -> new Signal(stage, "<file>", name, snapshot.counts().get(name), target)).toList();
        return new Contribution(stage, signals, List.of());
    }

    private static Contribution lexical(Snapshot snapshot) {
        M3ProblemSignature signature = M3ProblemSignature.fromSource(snapshot.sourcePath(), snapshot.masked());
        List<Signal> signals = new ArrayList<>();
        List<SignalRow> rows = new ArrayList<>();
        for (M3ProblemSignature.Candidate candidate : signature.candidates()) {
            String pattern = "algorithm:" + candidate.shape().name().toLowerCase(Locale.ROOT);
            signals.add(new Signal(Stage.MASKED_CUES, "<file>", pattern, candidate.score(), "NOMINATION_ONLY"));
            rows.add(new SignalRow(snapshot.sourcePath(), "<file>", "<algorithm>", "ALGORITHM_SHAPE_CUE",
                    candidate.score(), 1, "PROBLEM_RECIPE_PLANNER", pattern, "CANDIDATE_ONLY"));
        }
        return new Contribution(Stage.MASKED_CUES, signals, rows);
    }

    private static Contribution candidates(Map<Stage, Contribution> contributions, Snapshot snapshot) {
        List<Signal> signals = new ArrayList<>();
        for (Stage stage : RECOGNIZERS) {
            for (Signal signal : contributions.get(stage).signals()) {
                signals.add(new Signal(Stage.CANDIDATES, signal.key(), "REVIEW_" + signal.code(),
                        signal.observed(), signal.target()));
            }
        }
        snapshot.repeatedBodies().entrySet().stream().filter(entry -> entry.getValue() > 1)
                .sorted(Map.Entry.comparingByKey())
                .forEach(entry -> signals.add(new Signal(Stage.CANDIDATES, entry.getKey(),
                        "REPEATED_BODY_CUE", entry.getValue(), "CONTRACT_COMPARISON_REQUIRED")));
        return new Contribution(Stage.CANDIDATES, signals, List.of());
    }

    private static Contribution risks(Map<Stage, Contribution> contributions) {
        List<Signal> signals = new ArrayList<>();
        signals.add(new Signal(Stage.CONTRACT_RISK, "<file>", "BEHAVIOR_AND_DATAFLOW_UNPROVEN", 1, "HOLD"));
        signals.add(new Signal(Stage.CONTRACT_RISK, "<file>", "NO_PROMOTION_AUTHORITY", 1, "HOLD"));
        for (Signal signal : contributions.get(Stage.EFFECT_CONTRACT).signals()) {
            signals.add(new Signal(Stage.CONTRACT_RISK, signal.key(), "REVIEW_" + signal.code(), signal.observed(), "HOLD"));
        }
        if (!contributions.get(Stage.MASKED_CUES).signals().isEmpty()) {
            signals.add(new Signal(Stage.CONTRACT_RISK, "<file>", "LEXICAL_CUES_ARE_NOT_PROOF", 1, "HOLD"));
        }
        return new Contribution(Stage.CONTRACT_RISK, signals, List.of());
    }

    static Map<String, Signal> join(List<Signal> signals, int budget) {
        TreeMap<String, Signal> joined = new TreeMap<>();
        for (Signal signal : signals) {
            Signal previous = joined.putIfAbsent(signal.key(), signal);
            if (previous != null && !previous.equals(signal)) throw new Refusal(Status.CONFLICTING_EVIDENCE);
            if (joined.size() > budget) throw new Refusal(Status.SIGNAL_BUDGET_EXHAUSTED);
        }
        return Collections.unmodifiableMap(joined);
    }

    private static List<StageReceipt> receipts(Map<Stage, Contribution> contributions, String sourceHash, String sourcePath) {
        EnumMap<Stage, String> roots = new EnumMap<>(Stage.class);
        List<StageReceipt> receipts = new ArrayList<>();
        for (Stage stage : Stage.values()) {
            List<Stage> parents = switch (stage) {
                case INVENTORY -> List.of();
                case STRUCTURE, CONTROL_FLOW, EFFECT_CONTRACT, MASKED_CUES -> List.of(Stage.INVENTORY);
                case CANDIDATES -> RECOGNIZERS;
                case CONTRACT_RISK -> List.of(Stage.CANDIDATES, Stage.EFFECT_CONTRACT);
                case FIXED_POINT -> List.of(Stage.CONTRACT_RISK);
            };
            List<String> fields = new ArrayList<>(List.of(VERSION, sourcePath, sourceHash, stage.name()));
            for (Stage parent : parents) {
                fields.add(parent.name());
                fields.add(Objects.requireNonNull(roots.get(parent), "missing DAG parent"));
            }
            TreeSet<String> signalRoots = new TreeSet<>();
            contributions.get(stage).signals().forEach(signal -> signalRoots.add(signal.root()));
            fields.addAll(signalRoots);
            String root = SealHash.frame(fields.toArray(String[]::new));
            roots.put(stage, root);
            receipts.add(new StageReceipt(stage, parents, root, signalRoots.size()));
        }
        return List.copyOf(receipts);
    }

    static final class Refusal extends RuntimeException {
        private static final long serialVersionUID = 1L;
        final Status status;
        Refusal(Status status) { super(status.name()); this.status = status; }
    }

    static final class ReceiptTable extends DataTable<ReceiptRow> {
        ReceiptTable(Recipe recipe) {
            super(recipe, "M3 signal chain receipts", "Source-bound deterministic evidence DAG; no promotion authority.");
        }
    }

    static final class EvidenceTable extends DataTable<EvidenceRow> {
        EvidenceTable(Recipe recipe) {
            super(recipe, "M3 signal chain evidence", "All completed stage facts; candidate-only, never semantic replacement proof.");
        }
    }

    static final class DagTable extends DataTable<DagRow> {
        DagTable(Recipe recipe) {
            super(recipe, "M3 signal chain DAG", "Handler dependency roots in deterministic topological order.");
        }
    }

    public record EvidenceRow(
            @Column(displayName = "Source", description = "Repository-relative source.") String sourcePath,
            @Column(displayName = "Source SHA", description = "Exact supplied source identity.") String sourceSha256,
            @Column(displayName = "Stage", description = "Evidence producer, not a promotion authority.") String stage,
            @Column(displayName = "Subject", description = "Source-bound subject, not a semantic equivalence id.") String subject,
            @Column(displayName = "Code", description = "Typed fact or nomination.") String code,
            @Column(displayName = "Observed", description = "AST count or lexical candidate score.") int observed,
            @Column(displayName = "Target", description = "Next review lane or hold condition.") String target,
            @Column(displayName = "Root", description = "Length-framed evidence hash.") String root) { }

    public record DagRow(
            @Column(displayName = "Source", description = "Repository-relative source.") String sourcePath,
            @Column(displayName = "Stage", description = "Handler id.") String stage,
            @Column(displayName = "Parents", description = "Ordered prerequisite handler ids.") String parents,
            @Column(displayName = "Root", description = "Source, parent and evidence-bound handler root.") String root,
            @Column(displayName = "Signals", description = "Unique facts owned by the handler.") int signals) { }

    public record ReceiptRow(
            @Column(displayName = "Source", description = "Exact supplied LST source path.") String sourcePath,
            @Column(displayName = "SHA-256", description = "Source hash, empty before source admission.") String sourceSha256,
            @Column(displayName = "Status", description = "Evidence completion or typed execution residue.") String status,
            @Column(displayName = "Passes", description = "Evidence join passes, not source transformation cycles.") int passes,
            @Column(displayName = "Root", description = "DAG root; empty on incomplete execution.") String root,
            @Column(displayName = "Signals", description = "Completed unique evidence count.") int signals,
            @Column(displayName = "Residue", description = "Contract/effect risk or execution failure codes.") String residue,
            @Column(displayName = "Mutation", description = "Always false.") boolean mutationAuthority,
            @Column(displayName = "Promotion", description = "Always false.") boolean promotionAuthority) { }
}

